 [h('1. Requirements checked on 18 October 2026'),table([['Item','Current public evidence'],['Event','4th Annual Open Scientific Intelligence Hackathon; physical sciences and mathematics'],['Team','FAQ recommends 3-10 people, with no enforced size limit. No mandatory minimum is stated.'],['Event dates','21-22 October 2026; local start time on 21 October'],['Deadline','22 October, 7:00 PM CDT (UTC-5) = 23 October, 08:00 Beijing time = 23 October, 01:00 London BST'],['Current agenda','Submission is a social-media post; it can include a demo/presentation of up to 4 minutes and a write-up of up to 1 page.'],['Registration','All participants register for the main event. In-person participants also follow their site requirements.']]),
 p('Sources: <link href="https://llmhackathon.github.io/">official homepage/FAQ</link>; <link href="https://llmhackathon.github.io/agenda/">2026 agenda</link>; <link href="https://llmhackathon.github.io/sites/">site registration instructions</link>; <link href="https://luma.com/ku88xh92">Luma registration</link>.'),
 h('The public pages are not fully synchronized'),p('The separate Submission Guidelines page still shows a September 12 deadline and a two-minute video limit from the previous event. Its Google Form link has not been verified as the 2026 submission form. Use the explicitly dated 2026 agenda for preparation, and check the organizer\'s Slack/published instructions before posting or submitting. A two-minute alternative script is included for flexibility. The full article is optional supporting material, not a replacement for the one-page item.'),p('The homepage explicitly includes scientific software and mathematics. Some judging text still refers only to materials and chemistry; treat impact, novelty and scalability as useful presentation questions, not a fully confirmed 2026 scoring rubric. No public prior-work policy was located in the checked pages. This pack records a pre-event baseline and does not assert eligibility of all existing work.'),
 h('Prepared package'),p('One-page PDF; six-page technical article with three executed-data figures; editable HTML sources; copy-ready project description and social copy; four-minute and two-minute presentation scripts; case data and model recipes; source fingerprints; current numerical source and tests. An additional cooling figure appears on the website. The package has not been posted or submitted. Author: Niu Te, Imperial College London.')],

 [h('2. Copy-ready project fields'),table([['Field','Suggested entry'],['Project / team name','PhaseAtlas'],['Author / team member','Niu Te'],['Affiliation','Imperial College London'],['Area','Scientific software; mathematics; computational physics'],['Title',TITLE],['Source URL','https://github.com/NIU-55383/PhaseAtlas'],['Existing host','https://phaseatlas.onrender.com/ - verify the final release before submission'],['Development / runtime AI','AI-assisted development; no external LLM call during numerical simulation']]),
 h('Short description'),p('PhaseAtlas is a browser workbench that turns editable PDE models into animated, inspectable experiments. It combines controlled refinement, boundary-balance checks, travelling-wave diagnostics and parameter maps with reusable experiment records. Robin boundary cooling provides an application example; a fourth-order front connects the platform to nonlinear-wave research. The focus is reproducible numerical evidence rather than a claim to solve every PDE.'),
 h('Contribution / differentiation'),p('The project combines three research tasks in one workflow: checking numerical resolution and provenance, separating wave motion from deformation, and mapping a user-defined response while preserving every run. These individual methods are established; the contribution is their independent implementation and integration. Ninety mathematical and numerical tests pass in the current snapshot. No quantified superiority over another solver or proven user productivity gain is claimed.'),
 h('Prior-work disclosure'),p('The original MAE03 mathematics and the 18 October 2026 software baseline were developed before the event. The package records that baseline. Describe only changes actually completed on October 21-22 as event-period work, with dated commits or an equivalent change record. The current article and summary do not claim work occurred during a future event.'),
 h('Fields requiring a final human entry'),p('The confirmed 2026 submission form; your contact email if requested; the public video/post URL after publication; a verified URL for the newly deployed release; and a factual event-period contribution statement. No form was submitted and no message was sent on your behalf.')],

 [h('3. Four-minute presentation script'),p('Target: about 3 minutes 55 seconds. Rehearse and measure the final recording; edit pauses to stay below the announced limit. Pre-run studies so solver waiting time does not consume the presentation. Use the local reviewed release until the same version is deployed.'),*sum(([h(t),p('<b>Screen:</b> '+screen),p(words)] for t,screen,words in SCRIPT4),[])],

 [h('4. Two-minute alternative'),p('Use if the organizer confirms the shorter legacy limit. Target: about 1 minute 55 seconds; time the actual narration.'),*sum(([h(t),p('<b>Screen:</b> '+screen),p(words)] for t,screen,words in SCRIPT2),[]),
 h('5. Final submission checks'),p('1. Confirm the current form and prior-work policy from the organizer. Register every actual team member.<br/>2. Record the actual event-period changes separately from this baseline.<br/>3. Deploy the reviewed source and open the demo, PDF and JSON links in a signed-out browser.<br/>4. Record and time the presentation. This package supplies scripts, not a finished narrated video.<br/>5. Publish the intended social post/video only after reviewing its content and URLs.<br/>6. Complete the official form if required and retain its confirmation before the deadline.'),
 p('Detailed social copy is provided as social-post.txt. This kit gives suggested fields; the current 2026 form schema has not been independently confirmed. Team size: the official FAQ recommends 3-10 but imposes no size limit; do not describe three as a required minimum.')]
